  }
  function hpScale(w) {
    let m = 1000;
    for (let i = 1; i < w; i++) m = Math.floor(m * 108 / 100);
    return m;
  }
  function position(enemy) {
    const route = enemy.air ? AIR_ROUTE : GROUND_ROUTE;
    let left = enemy.progress;
    for (let i = 0; i < route.length - 1; i++) {
      const a = route[i], b = route[i + 1];
      const len = Math.abs(b[0] - a[0]) * 100 + Math.abs(b[1] - a[1]) * 100;
      if (left <= len) {
        return [a[0] * 100 + 50 + (b[0] === a[0] ? 0 : (b[0] > a[0] ? left : -left)),
          a[1] * 100 + 50 + (b[1] === a[1] ? 0 : (b[1] > a[1] ? left : -left))];
      }
      left -= len;
    }
    const p = route[route.length - 1];
    return [p[0] * 100 + 50, p[1] * 100 + 50];
  }
  function routeLength(air) { return air ? 2600 : 4600; }
  function armorFor(type, w) {
    if (type === 0) return Math.floor(w / 4);
    if (type === 3) return 6 + w;
    return 0;
  }
  function addEnemy(type, w, progress) {
    const air = type === 2 ? 1 : 0;
    const maxHp = type === 6 ? 1 : Math.floor(BASE_HP[type] * hpScale(w) / 1000);
    const e = { id: nextId++, type, wave: w, hp: maxHp, maxHp, progress: progress || 0,
      air, armor: armorFor(type, w), speed: SPEED[type], slow: 0, age: 0, x: 0, y: 0 };
    const p = position(e);
    e.x = p[0]; e.y = p[1];
    enemies.push(e);
    return e;
  }
  function view(e) {
    return { id: e.id, type: ENEMY_TYPES[e.type], hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y,
      air: e.air, armor: e.armor, speed: e.speed, slowed: e.slow > 0 ? 1 : 0,
      remaining: routeLength(e.air) - e.progress };
  }
  function stateView(tick) {
    return { tick, wave, gold, baseHp,
      slots: slots.map(s => ({ slot: s.slot, x: s.x, y: s.y,
        turret: s.turret ? { type: TYPES[s.turret.type], tier: s.turret.tier, spent: s.turret.spent } : null })),
      enemies: enemies.slice().sort((a,b) => a.id - b.id).map(view), nextWave: upcomingWave.slice() };
  }
  function turretDamage(t) {
    if (t.tier === 1) return DAMAGE[t.type];
    if (t.tier === 2) return Math.floor(DAMAGE[t.type] * 16 / 10);
    return Math.floor(Math.floor(DAMAGE[t.type] * 16 / 10) * 16 / 10);
