  }
  let currentTick = 0;
  if (recordFrames) frames.push(snapshot(0));
  for (currentTick = 0; currentTick < maxTicks; currentTick++) {
    const frame = recordFrames ? frames[currentTick] : null;
    if (currentTick >= 20 && (currentTick - 20) % 40 === 0) {
