      if (frame) frame.events.push({ kind: "wave", wave });
    }
    if (spawnQueue.length && spawnQueue[0].tick === currentTick) {
      while (spawnQueue.length && spawnQueue[0].tick === currentTick) {
        const q = spawnQueue.shift();
        addEnemy(q.type, q.wave, 0);
      }
    }
    enemies.sort((a,b) => a.id - b.id);
    let fell = false;
    for (let i = 0; i < enemies.length; i++) {
