      hideCountdown(); simTime = 0; scrubber.value = "0"; playbackState = PAUSED; icons(false); render(simTime);
    } else if (playbackState === PAUSED) setPlaying();
    else if (playbackState === ENDED) { simTime = 0; scrubber.value = "0"; hideCountdown(); setPlaying(); }
    updateAudio(playbackState, simTime, simTime);
  });
  refire.addEventListener("click", () => {
    hideCountdown(); simTime = 0; scrubber.value = "0"; holdElapsed = 0;
    playbackState = REFIRE_HOLD; icons(true); render(simTime); updateAudio(playbackState, 0, 0);
  });
  document.querySelectorAll(".speed-pill").forEach(pill => pill.addEventListener("click", () => {
    playbackSpeed = parseFloat(pill.dataset.speed);
    document.querySelectorAll(".speed-pill").forEach(other => {
      const active = other === pill; other.classList.toggle("is-active", active); other.setAttribute("aria-checked", active ? "true" : "false");
    });
  }));
  scrubber.addEventListener("input", () => {
    hideCountdown(); simTime = parseFloat(scrubber.value); playbackState = PAUSED; icons(false);
    render(simTime); updateAudio(playbackState, simTime, simTime);
  });
  scrubber.addEventListener("pointerdown", silenceAudio);
  window.addEventListener("resize", () => {
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setSize(window.innerWidth, window.innerHeight, false); fitCamera(); render(simTime);
  });
  function frame(now) {
    const rawDt = lastWall === null ? 0 : Math.max(0, (now - lastWall) / 1000);
    const dt = Math.min(rawDt, 0.1); lastWall = now;
    const oldTime = simTime;
    if (playbackState === COUNTDOWN) {
      countdownElapsed += dt;
      if (countdownElapsed >= 3) { hideCountdown(); setPlaying(); simTime = Math.min(DURATION, simTime + dt * playbackSpeed); }
      else {
        countdown.style.display = "block"; countdown.textContent = countdownElapsed < 1 ? "3" : countdownElapsed < 2 ? "2" : "1";
        simTime = 0; scrubber.value = "0";
      }
    } else if (playbackState === REFIRE_HOLD) {
      holdElapsed += dt; simTime = 0; scrubber.value = "0";
      if (holdElapsed >= 1) { setPlaying(); simTime = Math.min(DURATION, simTime + dt * playbackSpeed); }
    } else if (playbackState === PLAYING) simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
    if (playbackState === PLAYING) scrubber.value = simTime.toFixed(3);
    if (simTime >= DURATION && playbackState === PLAYING) {
      simTime = DURATION; scrubber.value = DURATION.toFixed(3); playbackState = ENDED; icons(false);
    }
    render(simTime); updateAudio(playbackState, oldTime, simTime);
    requestAnimationFrame(frame);
  }
  fitCamera(); icons(true); countdown.style.display = "block"; countdown.textContent = "3";
  render(0); requestAnimationFrame(frame);
})();
</script>"}

