{"path":"browser-check.js","content":"const { app, BrowserWindow } = require('electron');
const fs = require('fs');
app.commandLine.appendSwitch('no-sandbox');
app.commandLine.appendSwitch('disable-gpu-sandbox');
app.commandLine.appendSwitch('use-angle', 'swiftshader');
app.whenReady().then(async () => {
  const win = new BrowserWindow({ width: 1280, height: 650, show: false,
    webPreferences: { offscreen: true, backgroundThrottling: false } });
  const errors = [];
  win.webContents.on('console-message', (event, level, message) => {
    console.log('console', level, message);
    if (level >= 2) errors.push(message);
  });
  win.webContents.on('render-process-gone', (event, details) => errors.push(JSON.stringify(details)));
  await win.loadFile('index.html');
  await new Promise(resolve => setTimeout(resolve, 5200));
  const initial = await win.webContents.executeJavaScript(`({
    report: window.BENCH_REPORT,
    three: typeof THREE,
    scrubber: document.getElementById('scrubber').value,
    countdown: document.getElementById('countdown').textContent,
    countdownDisplay: getComputedStyle(document.getElementById('countdown')).display,
    toggle: document.getElementById('btn-toggle').getAttribute('aria-label'),
    canvases: document.querySelectorAll('canvas').length
  })`);
  console.log('INITIAL', JSON.stringify(initial));
  fs.writeFileSync('browser-playing.png', (await win.webContents.capturePage()).toPNG());
  const scrub = await win.webContents.executeJavaScript(`(() => {
    const s = document.getElementById('scrubber'); s.value = '50.000';
    s.dispatchEvent(new Event('input', { bubbles: true }));
    return { value: s.value, toggle: document.getElementById('btn-toggle').getAttribute('aria-label') };
  })()`);
  await new Promise(resolve => setTimeout(resolve, 300));
  console.log('SCRUB', JSON.stringify(scrub));
  fs.writeFileSync('browser-scrub.png', (await win.webContents.capturePage()).toPNG());
  const controls = await win.webContents.executeJavaScript(`(() => {
    document.querySelector('[data-speed="2.0"]').click();
    document.getElementById('btn-refire').click();
    const refire = { value: document.getElementById('scrubber').value,
      countdown: getComputedStyle(document.getElementById('countdown')).display,
      toggle: document.getElementById('btn-toggle').getAttribute('aria-label'),
      speed: document.querySelector('.speed-pill.is-active').dataset.speed };
    document.getElementById('btn-toggle').click();
    return { refire, paused: document.getElementById('btn-toggle').getAttribute('aria-label') };
  })()`);
  console.log('CONTROLS', JSON.stringify(controls));
  console.log('ERRORS', JSON.stringify(errors));
  app.quit();
}).catch(error => { console.error(error); app.exit(1); });
"}

{"path":"main-check.js","content":"const fs = require('fs');
const vm = require('vm');
const THREE = global.THREE = require('./three-check.js');
class Element {
  constructor(id) { this.id=id; this.style={}; this.attributes={}; this.listeners={}; this.value=id==='scrubber'?'0':''; this.textContent=id==='countdown'?'3':''; this.dataset={}; this.classList={toggle:(name,on)=>{this.active=on;}}; }
  addEventListener(name, fn) { (this.listeners[name]||(this.listeners[name]=[])).push(fn); }
  setAttribute(name,value) { this.attributes[name]=String(value); }
  getAttribute(name) { return this.attributes[name]; }
  click() { for(const fn of this.listeners.click||[]) fn({}); }
  fire(name) { for(const fn of this.listeners[name]||[]) fn({}); }
}
const ids=['stage','scrubber','countdown','btn-toggle','btn-refire','icon-play','icon-pause'];
const elements=Object.fromEntries(ids.map(id=>[id,new Element(id)]));
const pills=['0.25','0.5','1.0','2.0'].map(s=>{const e=new Element('pill');e.dataset.speed=s;e.active=s==='1.0';return e;});
const context2d={clearRect(){},fillText(){},set fillStyle(v){},set font(v){},set textAlign(v){},set textBaseline(v){}};
global.document={getElementById:id=>elements[id],createElement:()=>({width:0,height:0,getContext:()=>context2d}),querySelectorAll:q=>q==='.speed-pill'?pills:[]};
global.window=global; window.innerWidth=1280;window.innerHeight=650;window.devicePixelRatio=1;
const windowListeners={};window.addEventListener=(name,fn)=>{(windowListeners[name]||(windowListeners[name]=[])).push(fn);};
function param(value=0){return {value,setValueAtTime(v){this.value=v;},exponentialRampToValueAtTime(v){this.value=v;},setTargetAtTime(v){this.value=v;},cancelScheduledValues(){}};}
function node(){return {connect(){},start(){},stop(){if(this.onended)this.onended();}};}
class AudioContextMock {
  constructor(){this.currentTime=0;this.sampleRate=8000;this.destination={};}
  resume(){return Promise.resolve();}
  createGain(){return Object.assign(node(),{gain:param()});}
  createDynamicsCompressor(){return Object.assign(node(),{threshold:param(),knee:param(),ratio:param(),attack:param(),release:param()});}
  createBuffer(ch,len){return {getChannelData:()=>new Float32Array(len)};}
  createOscillator(){return Object.assign(node(),{frequency:param(),type:''});}
  createStereoPanner(){return Object.assign(node(),{pan:param()});}
  createBiquadFilter(){return Object.assign(node(),{frequency:param(),type:''});}
  createBufferSource(){return Object.assign(node(),{buffer:null,loop:false});}
}
window.AudioContext=AudioContextMock;
let renderCount=0;
THREE.WebGLRenderer=class {constructor(){this.shadowMap={};}setPixelRatio(){}setSize(){}setClearColor(){}clear(){}clearDepth(){}render(){renderCount++;}};
let raf=null;global.requestAnimationFrame=fn=>{raf=fn;};
const html=fs.readFileSync('index.html','utf8');
for(const id of ['rampart-strategy','rampart-sim']) vm.runInThisContext(html.split(`<script id="${id}">`)[1].split('</script>')[0]);
const main=html.match(/<script>([\s\S]*?)<\/script>/)[1];
vm.runInThisContext(main);
console.log('launch',JSON.stringify(window.BENCH_REPORT),'renders',renderCount);
for(let i=0;i<210;i++){const fn=raf;fn(i*16.6667);}
console.log('playing',elements.scrubber.value,elements.countdown.style.display,elements['btn-toggle'].attributes['aria-label']);
for(const value of ['50.000','82.300','100.000','0.000','50.000']){elements.scrubber.value=value;elements.scrubber.fire('input');}
console.log('scrub',elements.scrubber.value,elements['btn-toggle'].attributes['aria-label'],'renders',renderCount);
pills[3].click();elements['btn-refire'].click();
for(let i=0;i<65;i++){const fn=raf;fn(4000+i*16.6667);}
console.log('refire',elements.scrubber.value,'speedActive',pills[3].active,'countdown',elements.countdown.style.display);
elements['btn-toggle'].click();elements['btn-toggle'].click();
(windowListeners.resize||[]).forEach(fn=>fn({}));
console.log('final ok',renderCount);
"}
